import { useId, useRef, useState } from "react";
import { __ } from '@wordpress/i18n';
import { SketchPicker } from 'react-color';
import Button from './Button';
import SbUtils from '../../Utils/SbUtils'
import { useDismissable } from '../../a11y/useDismissable'


const ColorPicker = ( props ) => {
    const   [ colorPickerActive, setColorPickerActive ] = useState( false ),
            attrList = [
                {
                    'minimalist' : false
                },
            ],
            parentActionsList =  [ 'onClick'  ];

    // a11y (SMASH-1377, WCAG 2.1.2 No Keyboard Trap): useDismissable closes the
    // popup on BOTH outside-click and Escape. The legacy useOutsideClick lacked
    // Escape, so keyboard users who opened the picker had no way out. Canonical
    // dismissable pattern — matches the v2 ColorPicker.
    const ref = useRef( null );
    useDismissable( ref, () => {
       setColorPickerActive( false )
    }, { disabled: !colorPickerActive } );

    // a11y (SMASH-1377, parity with master SB_Colorpicker_Control): advertise the
    // popup as a dialog and wire the trigger to it (aria-haspopup + aria-controls).
    const popupId = useId();

    const changeColorValue = ( color, event ) => {
        let colorValue = color.hex;
        if(color.rgb.a !== 1){
            colorValue = `rgba(${color.rgb.r}, ${color.rgb.g}, ${color.rgb.b}, ${color.rgb.a})`
        }
        props.onChange( colorValue )
    }

    const resetColor = () => {
        props.onChange( props?.default || '' )
    }

    return (
        <div
            ref={ ref }
            className='sb-colorpicker-ctn sb-fs'
            { ...SbUtils.getElementAttributes( props, attrList ) }
            data-active={ colorPickerActive }
            data-disabled={ props?.disabled }
            { ...SbUtils.getElementActions( props, parentActionsList ) }
        >
            <button
                type='button'
                aria-label={ props?.ariaLabel || __( 'Choose color', 'sb-customizer' ) }
                aria-expanded={ colorPickerActive }
                aria-haspopup="dialog"
                aria-controls={ popupId }
                disabled={ props?.disabled === true }
                className='sb-button-reset sb-colorpicker-content sb-tr-2'
                onClick={ () => {
                    if( props?.disabled === false ){
                        setColorPickerActive( true )
                    }
                }}
            >
                <div className='sb-colorpicker-swatch' style={ { background: props?.value } }></div>
                {
                    !props.props &&
                    <div className='sb-colorpicker-value sb-text-tiny'>{ props?.value }</div>
                }
            </button>
            <div
                className='sb-colorpicker-popup sb-tr-1'
                id={ popupId }
                // a11y (SMASH-1377): only expose dialog semantics while the popup
                // is actually open. A closed popup is visibility:hidden, so a
                // permanent role="dialog" advertised a non-existent dialog to AT —
                // and any third-party "trap focus inside [role=dialog]" observer
                // (e.g. a sibling SB plugin's builder focus-trap loaded on the same
                // admin page) would latch onto the hidden picker and trap Tab in
                // the surrounding panel. Gate the role on the open state.
                role={ colorPickerActive ? 'dialog' : undefined }
                aria-label={ colorPickerActive ? __( 'Color picker', 'sb-customizer' ) : undefined }
            >
                <SketchPicker
                    color={ props?.value }
                    onChange={ changeColorValue }
                />
                <Button
                    text='Reset'
                    size='small'
                    full-width='true'
                    type='secondary'
                    boxshadow='false'
                    customClass='sb-bold sb-text-tiny sb-dark-text'
                    onClick={ () => {
                        resetColor()
                    } }
                />
            </div>
        </div>
    )
}

export default ColorPicker;
