import SbUtils from '../../Utils/SbUtils'

const Switcher = ( props ) => {

    const slug = 'sb-switcher-ctn',
        actionsList =  [ 'onChange' ],
        classesList =  [ 'size' ];

    const hasVisibleLabel = Boolean( props?.label );

    return (
        <>
            <label
                className={ SbUtils.getClassNames( props, slug, classesList ) }
            >
                {/*
                    SMASH-1377 round-5 (a11y): role="switch" advertises this
                    control as a toggle switch (not a plain checkbox) to screen
                    readers. On a native <input type="checkbox"> the `checked`
                    state is mapped to the switch automatically, so aria-checked
                    would be redundant. The CSS rule for .sb-switcher-ctn input
                    now uses visually-hidden styling (not display:none) so the
                    input remains focusable via Tab and natively activates with
                    Space.
                */}
                <input
                    type="checkbox"
                    role="switch"
                    aria-label={ !hasVisibleLabel ? props?.ariaLabel : undefined }
                    checked={ props?.value === props?.enabled }
                    disabled={ props?.disabled }
                    { ...SbUtils.getElementActions( props, actionsList ) }
                />
                <span className='sb-switcher-slider'></span>
                {
                    props?.label &&
                    <span className={(props?.labelStrong === true ? 'sb-bold ' : '') + 'sb-el-label sb-text-small' 
                    + (props?.inactive ? ' sb-light-text' : '')}
                        dangerouslySetInnerHTML={{__html:  props.label.replace(/\s/g, '&nbsp;')  }}>
                    </span>
                }
                {SbUtils.printRocketIcon( props?.inactive ) }
            </label>

        </>
    )

}

export default Switcher;