import { __ } from '@wordpress/i18n';

const TopNoticeBar = ( props ) => {
    return (
        props?.active &&
        <div
            className="sb-noticebar-ctn"
            data-type={ props?.type ? props?.type : 'default' }
        >
            <span className="sb-noticebar-heading">
                { props?.heading }
                { props?.actionText &&
                    <button
                        type='button'
                        className='sb-button-reset sb-noticebar-action sb-bold'
                        onClick={ () => {
                            props?.actionClick &&
                                props?.actionClick()
                        }}
                    >
                        {props?.actionText}
                    </button>
                }
            </span>
            {
                (props?.close !== false || props?.close === undefined) &&
                <button
                    type='button'
                    aria-label={ __( 'Close', 'sb-customizer' ) }
                    className='sb-button-reset sb-cls-ctn sb-modal-cls'
                    onClick={ () => {
                        props?.onClose &&
                            props.onClose()
                    }}
                >
                </button>
            }

        </div>
    )
}

export default TopNoticeBar;