import * as RadixTabs from '@radix-ui/react-tabs';

/**
 * Canonical Tabs primitive for sb-customizer.
 *
 * Wraps @radix-ui/react-tabs and provides:
 *   - role="tablist" / "tab" / "tabpanel"
 *   - aria-controls / aria-selected wiring
 *   - Arrow key navigation (Left/Right by default)
 *   - Home/End to first/last tab
 *   - Roving tabindex (only active tab is in tab order)
 *   - Focus management on tab activation
 *
 * Use the `asChild` prop on Tab/TabList/TabPanel to attach Radix behavior
 * to existing markup. Example:
 *
 *   <Tabs value={active} onValueChange={setActive}>
 *     <TabList asChild>
 *       <div className="sb-customizer-sidebar-tabs">
 *         <Tab asChild value="customize">
 *           <div className="sb-customizer-sidebar-tab">{label}</div>
 *         </Tab>
 *       </div>
 *     </TabList>
 *     <TabPanel asChild value="customize">
 *       <div className="sb-customizer-sidebar-panel">{...}</div>
 *     </TabPanel>
 *   </Tabs>
 *
 * Reference: .pitch/wcag-accessibility-audit/react-canonical-pattern.md (PR 1).
 */
export const Tabs = RadixTabs.Root;
export const TabList = RadixTabs.List;
export const Tab = RadixTabs.Trigger;
export const TabPanel = RadixTabs.Content;
