import SbUtils from '../../Utils/SbUtils'

const Type = (props) => {

    // a11y (SMASH-1377 v3 fix): the tile is the primary interactive control
    // for picking a feed type. Previously a <div onClick> — non-focusable,
    // unannounced as a control, and not activatable by Enter/Space. Promote
    // to a real <button> and strip native chrome with `sb-button-reset` so
    // the existing tile visuals (.sb-type-item) are preserved unchanged.
    // Mirrors the Common/Template.js tile pattern.
    return (
        <button
            type='button'
            className={'sb-type-item sb-button-reset' + (props?.customClass ? ' ' + props?.customClass : '')}
            data-checked={props.isChecked}
            data-ispro={props.isFeedTypePro}
            data-type={props.type}
            aria-pressed={props.isChecked ? 'true' : 'false'}
            onClick={() => {
                if (props?.onClick)
                    props.onClick()
            }}
        >
            {props.isChecked &&
                SbUtils.printIcon('checked', 'sb-type-checked-svg')
            }

            <div className='sb-type-icon sb-fs'>
                {SbUtils.printIcon(props.type, 'sb-type-svg')}
            </div>

            <div className='sb-type-info-wrap sb-fs'>
                <div className='sb-type-name sb-bold sb-text-small'>
                    {props.title}
                    {
                        props.isFeedTypePro &&
                        SbUtils.printIcon('rocket', 'sb-type-name-svg', false, 12)
                    }
                </div>
                {props.info &&
                    <div className='sb-type-info sb-text-tiny'>
                        {props.info}
                    </div>
                }
            </div>
        </button>
    )
}

export default Type;
