import { useState, useEffect } from 'react'
import { __, sprintf } from '@wordpress/i18n'
import SbUtils from '../../Utils/SbUtils'
import Button from './Button';
import Checkbox from './Checkbox';

const Source = ( props ) => {

    const [ reconnecting, setReconnecting ] = useState( false );

    // The reconnect flow redirects away on success; if that never happens
    // (redirect blocked, network error, user cancels) reset so the button
    // doesn't stay stuck in "Reconnecting…".
    useEffect( () => {
        if ( ! reconnecting ) {
            return;
        }
        const timer = setTimeout( () => setReconnecting( false ), 10000 );
        return () => clearTimeout( timer );
    }, [ reconnecting ] );

    const reconnect = ( event ) => {
        event?.stopPropagation?.()
        event?.preventDefault?.()
        if ( reconnecting ) {
            return;
        }
        setReconnecting( true )
        if ( props?.onReconnectClick )
            props.onReconnectClick()
    }

    return (
        <div
            className={ 'sb-source-item ' + ( props?.hasError ? 'sb-source-item-error ' : '' ) + ( props?.customClass ? props?.customClass : '' ) }
            data-checked={props.isChecked}
            onClick={ ( event ) => {
                event.stopPropagation()
                // a11y (SMASH-1377 v3): when this row has a checkbox/radio, let
                // that control own activation. Calling preventDefault() here
                // cancelled the checkbox's native toggle and desynced the
                // controlled <input> — keyboard Space selected the source
                // (data-checked flipped) but the tickbox stayed visually
                // unchecked. For clicks originating in the checkbox, bail out so
                // the checkbox's own onChange handles the toggle and stays in
                // sync. Row clicks elsewhere still toggle via props.onClick.
                if ( event.target.closest && event.target.closest( '.sb-checkbox-ctn' ) ) {
                    return;
                }
                event.preventDefault()
                if( props?.onClick )
                    props.onClick()
            }}
        >
            <div className='sb-source-item-top sb-fs'>
                {
                    ( props?.checkbox || props?.radiobox ) &&
                    <div className='sb-source-item-box'>
                        {
                            props.checkbox &&
                            <Checkbox
                                value={ props.isChecked }
                                enabled={ true }
                                // a11y (SMASH-1377 v3): the source name lives in
                                // a sibling .sb-source-item-info node, so the
                                // checkbox had no accessible name — screen
                                // readers announced only "checkbox". Name it
                                // after the source so SR users hear which source
                                // they are selecting.
                                ariaLabel={ props.name }
                                onChange={ () => {
                                    if( props?.onClick )
                                        props.onClick()
                                }}
                            />
                        }
                        {
                            props.radiobox &&
                            <Checkbox
                                value={ props.isChecked }
                                enabled={ true }
                                ariaLabel={ props.name }
                                onChange={ () => {
                                    if( props?.onClick )
                                        props.onClick()
                                }}
                            />
                        }
                    </div>
                }
                <div className='sb-source-item-icon'>
                    <span className='sb-source-item-avatar'>
                        <img src={ props.avatar } alt="" aria-hidden="true" />
                        {
                            props?.hasError &&
                            <span className='sb-source-item-error-badge'>
                                { SbUtils.printIcon( 'exclamation', false, false, 9 ) }
                            </span>
                        }
                    </span>
                </div>

                <div className='sb-source-item-info'>
                    <span className='sb-text-small sb-bold'>{ props.name }</span>
                    {
                        props?.hasError
                            ? <span className='sb-source-error-wrap'>
                                <span className='sb-source-error-label'>{ __('Source Invalid', 'sb-customizer') }</span>
                                <span className='sb-source-error-sep'>·</span>
                                <Button
                                    text={ reconnecting ? __('Reconnecting…', 'sb-customizer') : __('Reconnect', 'sb-customizer') }
                                    icon='reset'
                                    type='secondary'
                                    size='small'
                                    boxshadow={false}
                                    iconSize='11'
                                    loading={ reconnecting }
                                    disabled={ reconnecting }
                                    customClass='sb-source-reconnect-btn'
                                    onClick={ reconnect }
                                />
                            </span>
                            : <span className='sb-dark2-text sb-text-tiny'>{ __('Used in 0 Feeds', 'sb-customizer') }</span>
                    }
                </div>
                {
                    ( props?.removeIcon || props?.infoIcon ) &&
                        <div className='sb-source-act-ctn'>
                            {
                                props?.removeIcon &&
                                <div className='sb-source-item-remove-icon sb-source-act-icon-ctn'>
                                    <button
                                        type='button'
                                        aria-label={ sprintf(
                                            /* translators: %s: source name */
                                            __( 'Remove %s', 'sb-customizer' ),
                                            props.name
                                        ) }
                                        className='sb-button-reset sb-source-act-icon sb-tr-2'
                                        onClick={ ( event ) => {
                                            event.stopPropagation()
                                            if( props?.onRemoveClick )
                                                props.onRemoveClick()
                                        }}
                                    >
                                        { SbUtils.printIcon( 'trash', false, false, 11  ) }
                                    </button>
                                </div>
                            }
                            {
                                props?.infoIcon &&
                                <div className='sb-source-item-info-icon sb-source-act-icon-ctn'>
                                    <button
                                        type='button'
                                        aria-label={ sprintf(
                                            /* translators: %s: source name */
                                            __( '%s settings', 'sb-customizer' ),
                                            props.name
                                        ) }
                                        aria-expanded={ props?.isCollapsed === true }
                                        className='sb-button-reset sb-source-act-icon sb-tr-2'
                                        onClick={ ( event ) => {
                                            event.stopPropagation()
                                            props.onShowInfoClick()
                                        }}
                                    >
                                        { SbUtils.printIcon( 'cog', false, false, 15 ) }
                                    </button>
                                </div>
                            }
                        </div>
                }
            </div>
            {
                ( props?.infoIcon && props?.isCollapsed === true  ) &&
                <div className='sb-source-dp-info sb-fs'>
                    <div className='sb-source-dp-info-item'>
                        <strong>Open ID</strong>
                        <span>{ props.openId }</span>
                        <Button
                            icon='copy'
                            type='secondary'
                            size='small'
                            boxshadow={false}
                            ariaLabel={ __( 'Copy open ID', 'sb-customizer' ) }
                            onClick={ () => {
                                SbUtils.copyToClipBoard( props.openId, props.editorNotification )
                            } }
                        />
                    </div>
                </div>
            }
        </div>
    )
}

export default Source;