import { useEffect } from 'react'
import SbUtils from '../../Utils/SbUtils'
import { useAnnouncer } from '../../a11y/Announcer'

const Notification = ( props ) => {
    const announce = useAnnouncer();

    // Mirror visible notifications to the aria-live region so screen reader
    // users hear save / error / info toasts the same as sighted users see them.
    // 'error' type → assertive (interrupts); everything else → polite.
    useEffect(() => {
        if ( props?.active && props?.text ) {
            announce( props.text, { assertive: props?.type === 'error' } );
        }
    }, [ props?.active, props?.text, props?.type, announce ]);

    return (
        props?.active &&
        <div className='sb-notification-ctn'
            data-active={ props?.active ? 'shown' : 'hidden' }
            data-type={ props?.type || 'success' }
        >
            {
                props?.icon &&
                SbUtils.printIcon( props.icon, 'sb-notification-icon' )
            }
            <span className='sb-notification-text'>{ props.text }</span>
        </div>
    )
}

export default Notification;